use anyhow::{anyhow, Result};
use crossterm::{
    event::{self, Event, KeyCode, KeyEvent, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{
    backend::{Backend, CrosstermBackend},
    layout::{Constraint, Direction, Layout, Rect},
    style::{Color, Modifier, Style},
    text::{Line, Span},
    widgets::{Block, Borders, Paragraph, Wrap},
    Frame, Terminal,
};
use std::io;
use std::time::{Duration, Instant};

mod app;
mod git;
mod ui;
mod config;

use app::App;

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();

    if args.len() > 1 {
        match args[1].as_str() {
            "--help" | "-h" => {
                println!("A TUI tool to visualize Git commit graphs with branch genealogy\n");
                println!("Usage: executable\n");
                println!("Options:");
                println!("  -h, --help     Print help");
                println!("  -V, --version  Print version");
                return Ok(());
            }
            "--version" | "-V" => {
                println!("keifu 0.2.3");
                return Ok(());
            }
            _ => {
                println!("Unknown option: {}", args[1]);
                return Err(anyhow!("Unknown option"));
            }
        }
    }

    // Setup terminal
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Create app and run it
    let result = run_app(&mut terminal).await;

    // Restore terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    result
}

async fn run_app<B: Backend>(terminal: &mut Terminal<B>) -> Result<()> {
    let config = config::Config::load()?;
    let mut app = App::new(config).await?;

    let tick_rate = Duration::from_millis(250);
    let mut last_tick = Instant::now();

    loop {
        terminal.draw(|f| ui::draw(f, &mut app))?;

        let timeout = tick_rate
            .checked_sub(last_tick.elapsed())
            .unwrap_or_else(|| Duration::from_secs(0));

        if crossterm::event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                match key.code {
                    KeyCode::Char('q') | KeyCode::Esc => {
                        return Ok(());
                    }
                    KeyCode::Char('j') | KeyCode::Down => {
                        app.move_down();
                    }
                    KeyCode::Char('k') | KeyCode::Up => {
                        app.move_up();
                    }
                    KeyCode::Char('g') | KeyCode::Home => {
                        app.go_to_top();
                    }
                    KeyCode::Char('G') | KeyCode::End => {
                        app.go_to_bottom();
                    }
                    KeyCode::Char('l') | KeyCode::Right => {
                        app.select_right_branch();
                    }
                    KeyCode::Char('h') | KeyCode::Left => {
                        app.select_left_branch();
                    }
                    KeyCode::Tab => {
                        if key.modifiers.contains(KeyModifiers::SHIFT) {
                            app.select_prev_branch();
                        } else {
                            app.select_next_branch();
                        }
                    }
                    KeyCode::Char('[') => {
                        app.select_prev_branch();
                    }
                    KeyCode::Char(']') => {
                        app.select_next_branch();
                    }
                    KeyCode::Char('?') => {
                        app.toggle_help();
                    }
                    KeyCode::Char('@') => {
                        app.jump_to_head();
                    }
                    KeyCode::Enter => {
                        if app.help_open {
                            app.toggle_help();
                        } else {
                            app.checkout_selected().await?;
                        }
                    }
                    KeyCode::Char('b') => {
                        if !app.help_open {
                            app.show_branch_dialog();
                        }
                    }
                    KeyCode::Char('d') => {
                        if !app.help_open {
                            app.show_delete_dialog();
                        }
                    }
                    KeyCode::Char('f') => {
                        if !app.help_open {
                            app.fetch_from_origin().await?;
                        }
                    }
                    KeyCode::Char('r') | KeyCode::Char('R') => {
                        if !app.help_open {
                            app.refresh().await?;
                        }
                    }
                    KeyCode::Ctrl('d') => {
                        app.page_down();
                    }
                    KeyCode::Ctrl('u') => {
                        app.page_up();
                    }
                    KeyCode::Char(c) if app.input_mode => {
                        app.input.push(c);
                    }
                    KeyCode::Backspace if app.input_mode => {
                        app.input.pop();
                    }
                    _ => {}
                }
            }
        }

        if last_tick.elapsed() >= tick_rate {
            app.tick().await?;
            last_tick = Instant::now();
        }
    }
}
