use crate::config::Config;
use crate::git::{GitRepository, CommitInfo, BranchInfo};
use anyhow::Result;
use std::time::Instant;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum DialogMode {
    None,
    CreateBranch,
    DeleteBranch,
}

pub struct App {
    pub repo: GitRepository,
    pub commits: Vec<CommitInfo>,
    pub branches: Vec<BranchInfo>,
    pub selected_index: usize,
    pub selected_branch: Option<String>,
    pub scroll_offset: usize,
    pub help_open: bool,
    pub dialog_mode: DialogMode,
    pub input: String,
    pub input_mode: bool,
    pub config: Config,
    pub last_refresh: Instant,
    pub last_fetch: Instant,
}

impl App {
    pub async fn new(config: Config) -> Result<Self> {
        let repo = GitRepository::open(".")?;
        let commits = repo.get_commits()?;
        let branches = repo.get_branches()?;
        let head_branch = repo.get_head_branch()?;

        Ok(Self {
            repo,
            commits,
            branches,
            selected_index: 0,
            selected_branch: head_branch,
            scroll_offset: 0,
            help_open: false,
            dialog_mode: DialogMode::None,
            input: String::new(),
            input_mode: false,
            config,
            last_refresh: Instant::now(),
            last_fetch: Instant::now(),
        })
    }

    pub fn move_down(&mut self) {
        if self.selected_index < self.commits.len().saturating_sub(1) {
            self.selected_index += 1;
        }
    }

    pub fn move_up(&mut self) {
        if self.selected_index > 0 {
            self.selected_index -= 1;
        }
    }

    pub fn go_to_top(&mut self) {
        self.selected_index = 0;
    }

    pub fn go_to_bottom(&mut self) {
        self.selected_index = self.commits.len().saturating_sub(1);
    }

    pub fn page_down(&mut self) {
        self.selected_index = (self.selected_index + 10).min(self.commits.len().saturating_sub(1));
    }

    pub fn page_up(&mut self) {
        self.selected_index = self.selected_index.saturating_sub(10);
    }

    pub fn select_next_branch(&mut self) {
        if let Some(current) = &self.selected_branch {
            if let Some(pos) = self.branches.iter().position(|b| b.name == *current) {
                if pos < self.branches.len() - 1 {
                    self.selected_branch = Some(self.branches[pos + 1].name.clone());
                }
            }
        } else if !self.branches.is_empty() {
            self.selected_branch = Some(self.branches[0].name.clone());
        }
    }

    pub fn select_prev_branch(&mut self) {
        if let Some(current) = &self.selected_branch {
            if let Some(pos) = self.branches.iter().position(|b| b.name == *current) {
                if pos > 0 {
                    self.selected_branch = Some(self.branches[pos - 1].name.clone());
                }
            }
        } else if !self.branches.is_empty() {
            self.selected_branch = Some(self.branches[self.branches.len() - 1].name.clone());
        }
    }

    pub fn select_left_branch(&mut self) {
        // Select left branch at the same commit level
        if let Some(commit) = self.commits.get(self.selected_index) {
            let current_branches: Vec<_> = self.branches
                .iter()
                .filter(|b| b.commit_hash == commit.hash)
                .collect();

            if let Some(current) = &self.selected_branch {
                if let Some(pos) = current_branches.iter().position(|b| b.name == *current) {
                    if pos > 0 {
                        self.selected_branch = Some(current_branches[pos - 1].name.clone());
                    }
                }
            } else if !current_branches.is_empty() {
                self.selected_branch = Some(current_branches[0].name.clone());
            }
        }
    }

    pub fn select_right_branch(&mut self) {
        // Select right branch at the same commit level
        if let Some(commit) = self.commits.get(self.selected_index) {
            let current_branches: Vec<_> = self.branches
                .iter()
                .filter(|b| b.commit_hash == commit.hash)
                .collect();

            if let Some(current) = &self.selected_branch {
                if let Some(pos) = current_branches.iter().position(|b| b.name == *current) {
                    if pos < current_branches.len() - 1 {
                        self.selected_branch = Some(current_branches[pos + 1].name.clone());
                    }
                }
            } else if !current_branches.is_empty() {
                self.selected_branch = Some(current_branches[0].name.clone());
            }
        }
    }

    pub fn jump_to_head(&mut self) {
        if let Ok(head) = self.repo.get_head_branch() {
            if let Some(pos) = self.commits.iter().position(|c| c.is_head) {
                self.selected_index = pos;
                self.selected_branch = head;
            }
        }
    }

