use anyhow::Result;
use chrono::{DateTime, Local};
use git2::{Repository, Sort, ObjectType, Oid, BranchType, Reference};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct CommitInfo {
    pub hash: String,
    pub short_hash: String,
    pub message: String,
    pub author: String,
    pub date: String,
    pub parent_hashes: Vec<String>,
    pub is_head: bool,
}

#[derive(Debug, Clone)]
pub struct BranchInfo {
    pub name: String,
    pub commit_hash: String,
    pub is_remote: bool,
    pub is_current: bool,
}

#[derive(Debug, Clone)]
pub struct CommitDiff {
    pub additions: usize,
    pub deletions: usize,
    pub files_changed: Vec<String>,
}

pub struct GitRepository {
    repo: Repository,
}

impl GitRepository {
    pub fn open(path: &str) -> Result<Self> {
        let repo = Repository::open(path)?;
        Ok(GitRepository { repo })
    }

    pub fn get_commits(&self) -> Result<Vec<CommitInfo>> {
        let mut revwalk = self.repo.revwalk()?;
        revwalk.push_head()?;
        revwalk.set_sorting(Sort::TIME)?;

        let head_oid = if let Ok(head) = self.repo.head() {
            head.target()
        } else {
            None
        };

        let mut commits = Vec::new();
        for oid in revwalk {
            let oid = oid?;
            let commit = self.repo.find_commit(oid)?;

            let short_hash = format!("{}", oid.to_string().chars().take(7).collect::<String>());
            let message = commit.message()
                .unwrap_or("")
                .lines()
                .next()
                .unwrap_or("")
                .to_string();

            let author = commit.author();
            let author_str = format!("{}", author.name().unwrap_or("Unknown"));

            let date = DateTime::<Local>::from(commit.time()).format("%Y-%m-%d").to_string();

            let parent_hashes: Vec<String> = (0..commit.parent_count())
                .map(|i| commit.parent_id(i).unwrap_or_else(|_| Oid::zero()).to_string())
                .map(|s| s.chars().take(7).collect())
                .collect();

            let is_head = head_oid == Some(oid);

            commits.push(CommitInfo {
                hash: oid.to_string().chars().take(7).collect(),
                short_hash,
                message,
                author: author_str,
                date,
                parent_hashes,
                is_head,
            });
        }

        Ok(commits)
    }

    pub fn get_branches(&self) -> Result<Vec<BranchInfo>> {
        let mut branches = Vec::new();

        for branch in self.repo.branches(Some(BranchType::Local))? {
            let (branch, _) = branch?;
            let name = branch.name()?.unwrap_or("").to_string();

            if let Ok(reference) = branch.get() {
                if let Some(oid) = reference.target() {
                    let short_hash: String = oid.to_string().chars().take(7).collect();
                    let is_current = branch.is_head()?;

                    branches.push(BranchInfo {
                        name,
                        commit_hash: short_hash,
                        is_remote: false,
                        is_current,
                    });
                }
            }
        }

        // Add remote branches
