        let y = inner.y + i as u16;
        if y >= area.bottom() {
            break;
        }

        let is_selected = start + i == app.selected_index;
        let has_branches = app.branches.iter().any(|b| b.commit_hash == commit.short_hash);

        let mut branch_str = String::new();
        if has_branches {
            let branch_names: Vec<_> = app.branches
                .iter()
                .filter(|b| b.commit_hash == commit.short_hash)
                .map(|b| {
                    if b.is_current {
