        .title(" Commit Detail ")
        .borders(Borders::ALL);

    let inner = block.inner(area);
    f.render_widget(block, area);

    if let Some(commit) = app.get_selected_commit() {
        let mut lines = vec![
            Line::from(vec![
                Span::raw("Commit: "),
                Span::styled(commit.hash.clone(), Style::default().fg(Color::Yellow)),
            ]),
            Line::from(vec![
                Span::raw("Author: "),
                Span::raw(commit.author.clone()),
            ]),
            Line::from(vec![
                Span::raw("Date:   "),
                Span::raw(commit.date.clone()),
            ]),
        ];

        if !commit.parent_hashes.is_empty() {
            lines.push(Line::from(vec![
                Span::raw("Parent: "),
                Span::raw(commit.parent_hashes.join(", ")),
            ]));
        }

        lines.push(Line::from(""));
