fn draw_changed_files<B: Backend>(f: &mut Frame<B>, app: &App, area: Rect) {
    let block = Block::default()
        .title(" Changed Files ")
        .borders(Borders::ALL);

    let inner = block.inner(area);
    f.render_widget(block, area);

    if let Some(commit) = app.get_selected_commit() {
        let mut lines = vec![
            Line::from(format!("{} files changed  +{} -{}", 
                if let Ok(diff) = app.repo.get_commit_diff(&commit.hash) {
                    diff.files_changed.len()
                } else {
                    0
                },
                if let Ok(diff) = app.repo.get_commit_diff(&commit.hash) {
                    diff.additions
                } else {
                    0
                },
