fn draw_commits<B: Backend>(f: &mut Frame<B>, app: &App, area: Rect) {
    let block = Block::default()
        .title(" Commits ")
        .borders(Borders::ALL);

    let inner = block.inner(area);
    f.render_widget(block, area);

    // Draw commit graph
    let visible_height = inner.height as usize;
    let start = app.selected_index.saturating_sub(visible_height / 2);
    let end = (start + visible_height).min(app.commits.len());
    let start = start.min(app.commits.len());

    for (i, commit) in app.commits[start..end].iter().enumerate() {
        let y = inner.y + i as u16;
        if y >= area.bottom() {
            break;
        }

        let is_selected = start + i == app.selected_index;
        let has_branches = app.branches.iter().any(|b| b.commit_hash == commit.short_hash);

        let mut branch_str = String::new();
        if has_branches {
            let branch_names: Vec<_> = app.branches
                .iter()
                .filter(|b| b.commit_hash == commit.short_hash)
                .map(|b| {
                    if b.is_current {
                        format!("[{}]", b.name)
                    } else {
                        format!("[{}]", b.name)
                    }
                })
                .collect();
            branch_str = branch_names.join(" ");
        }

        let message_preview = if branch_str.is_empty() {
            commit.message.clone()
        } else {
            format!("{} {}", branch_str, commit.message)
        };

        let style = if is_selected {
            Style::default()
                .bg(Color::DarkGray)
                .fg(Color::White)
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default()
        };

