#!/usr/bin/env python3
import sys
import os
import subprocess
import json
from datetime import datetime
import curses
from dataclasses import dataclass
from typing import List, Optional, Dict, Tuple
import time
import re

# Simple TOML parser for basic config
def parse_toml_basic(content: str) -> Dict:
    """Parse a basic TOML file with minimal features"""
    result = {}
    current_section = None

    for line in content.split('\n'):
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        # Section headers
        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            current_section = section_name
            result[section_name] = {}
            continue

        # Key-value pairs
        if '=' in line:
            key, value = line.split('=', 1)
            key = key.strip()
            value = value.strip()

            # Parse value
            if value.lower() == 'true':
                value = True
            elif value.lower() == 'false':
                value = False
            elif value.isdigit():
                value = int(value)
            else:
                value = value.strip('"\'')

            if current_section:
                result[current_section][key] = value
            else:
                result[key] = value

    return result

# Config handling
@dataclass
class RefreshConfig:
    auto_refresh: bool = True
    refresh_interval: int = 10
    auto_fetch: bool = True
    fetch_interval: int = 60

@dataclass
class Config:
    refresh: RefreshConfig = None

    def __post_init__(self):
        if self.refresh is None:
            self.refresh = RefreshConfig()

def load_config() -> Config:
    config_home = os.environ.get('XDG_CONFIG_HOME')
    if not config_home:
        config_home = os.path.expanduser('~/.config')

    config_path = os.path.join(config_home, 'keifu', 'config.toml')

    try:
        if os.path.exists(config_path):
            with open(config_path, 'r') as f:
                data = parse_toml_basic(f.read())

            refresh_data = data.get('refresh', {})
            refresh = RefreshConfig(
                auto_refresh=refresh_data.get('auto_refresh', True),
                refresh_interval=refresh_data.get('refresh_interval', 10),
                auto_fetch=refresh_data.get('auto_fetch', True),
                fetch_interval=refresh_data.get('fetch_interval', 60),
            )
            return Config(refresh=refresh)
    except Exception:
        pass

    return Config()

# Git utilities
@dataclass
class CommitInfo:
    hash: str
    short_hash: str
    message: str
    author: str
    date: str
    parent_hashes: List[str]
    is_head: bool

@dataclass
class BranchInfo:
    name: str
    commit_hash: str
    is_remote: bool
    is_current: bool

class GitRepository:
    def __init__(self, path: str = '.'):
        self.path = path
        self.verify_git_repo()

    def verify_git_repo(self):
        try:
            subprocess.run(
                ['git', '-C', self.path, 'rev-parse', '--git-dir'],
                capture_output=True,
                check=True,
                timeout=5
            )
        except Exception as e:
            raise Exception(f"Not a git repository: {e}")

    def run_git(self, *args):
        cmd = ['git', '-C', self.path] + list(args)
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, check=False, timeout=10)
            return result.stdout, result.stderr, result.returncode
        except subprocess.TimeoutExpired:
            return "", "Timeout", 1

    def get_commits(self) -> List[CommitInfo]:
        commits = []

        # Get all commits - use a custom format to avoid parsing issues
        stdout, _, _ = self.run_git(
            'log', '--all', '--pretty=format:%H%n%h%n%s%n%an%n%ai%n%P%n--COMMIT_END--'
        )

        if not stdout:
            return commits

        # Split by commit delimiter
        commit_blocks = stdout.split('--COMMIT_END--')

        for block in commit_blocks:
            lines = block.strip().split('\n')
            if not lines or not lines[0]:
                continue

            try:
                hash_full = lines[0] if len(lines) > 0 else ''
                short_hash = lines[1] if len(lines) > 1 else ''
                message = lines[2] if len(lines) > 2 else ''
                author = lines[3] if len(lines) > 3 else 'Unknown'
                date_str = lines[4] if len(lines) > 4 else ''
                parents = lines[5].split() if len(lines) > 5 and lines[5] else []

                if not hash_full:
                    continue

                # Parse date
                try:
                    date_obj = datetime.fromisoformat(date_str.replace('Z', '+00:00'))
                    date = date_obj.strftime('%Y-%m-%d')
                except:
                    date = date_str[:10]

                # Check if HEAD
                head_out, _, _ = self.run_git('rev-parse', 'HEAD')
                is_head = head_out.strip() == hash_full

                parent_shorts = [p[:7] for p in parents]

                commits.append(CommitInfo(
                    hash=short_hash,
                    short_hash=short_hash,
                    message=message,
                    author=author[:20],
                    date=date,
                    parent_hashes=parent_shorts,
                    is_head=is_head,
                ))

            except (IndexError, ValueError) as e:
                continue

        return commits

    def get_branches(self) -> List[BranchInfo]:
        branches = []

        # Local branches
        stdout, _, _ = self.run_git('branch', '-v', '--format=%(refname:short)%09%(objectname:short)')
        for line in stdout.strip().split('\n'):
            if not line:
                continue
            parts = line.split('\t')
            if len(parts) >= 2:
                name = parts[0].strip()
                commit_hash = parts[1].split()[0] if parts[1] else ''
                if not commit_hash:
                    continue

                # Check if current
                is_current_out, _, _ = self.run_git('symbolic-ref', '--short', 'HEAD')
                is_current = is_current_out.strip() == name

                branches.append(BranchInfo(
                    name=name,
                    commit_hash=commit_hash,
                    is_remote=False,
                    is_current=is_current,
                ))

        # Remote branches
        stdout, _, _ = self.run_git('branch', '-r', '-v', '--format=%(refname:short)%09%(objectname:short)')
        for line in stdout.strip().split('\n'):
            if not line:
                continue
            parts = line.split('\t')
            if len(parts) >= 2:
                name = parts[0].strip()
                commit_hash = parts[1].split()[0] if parts[1] else ''
                if not commit_hash:
                    continue

                branches.append(BranchInfo(
                    name=name,
                    commit_hash=commit_hash,
                    is_remote=True,
                    is_current=False,
                ))

        return branches

    def get_head_branch(self) -> Optional[str]:
        stdout, _, code = self.run_git('symbolic-ref', '--short', 'HEAD')
        if code == 0:
            return stdout.strip()
        return None

    def checkout(self, target: str):
        _, _, code = self.run_git('checkout', target)
        return code == 0

    def fetch(self):
        _, _, code = self.run_git('fetch', 'origin')
        return code == 0

    def get_commit_diff(self, commit_hash: str) -> Tuple[int, int, List[str]]:
        # Get file stats
        stdout, _, _ = self.run_git('show', '--stat', commit_hash)

        files_changed = []
        additions = 0
        deletions = 0

        for line in stdout.split('\n'):
            if line and '|' in line and not line.startswith('commit'):
                parts = line.split('|')
                if len(parts) >= 2:
                    filename = parts[0].strip()
                    stats = parts[1].strip()
                    if filename:
                        files_changed.append(filename)
                        additions += stats.count('+')
                        deletions += stats.count('-')

        return additions, deletions, files_changed

# TUI Application
class App:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        self.config = load_config()
        self.repo = GitRepository('.')
        self.commits = []
        self.branches = []
        self.selected_index = 0
        self.selected_branch = None
        self.scroll_offset = 0
        self.help_open = False
        self.input = ""
        self.input_mode = False
        self.last_refresh = time.time()
        self.last_fetch = time.time()
        self.running = True

        # Initial load
        self.refresh_data()

    def refresh_data(self):
        try:
            self.commits = self.repo.get_commits()
            self.branches = self.repo.get_branches()
            self.selected_branch = self.repo.get_head_branch()
            self.last_refresh = time.time()
        except Exception:
            pass

    def move_down(self):
        if self.selected_index < len(self.commits) - 1:
            self.selected_index += 1

    def move_up(self):
        if self.selected_index > 0:
            self.selected_index -= 1

    def go_to_top(self):
        self.selected_index = 0

    def go_to_bottom(self):
        self.selected_index = max(0, len(self.commits) - 1)

    def page_down(self):
        self.selected_index = min(self.selected_index + 10, max(0, len(self.commits) - 1))

    def page_up(self):
        self.selected_index = max(0, self.selected_index - 10)

    def select_next_branch(self):
        if not self.branches:
            return
        if self.selected_branch is None:
            self.selected_branch = self.branches[0].name
        else:
            for i, b in enumerate(self.branches):
                if b.name == self.selected_branch and i < len(self.branches) - 1:
                    self.selected_branch = self.branches[i + 1].name
                    break

    def select_prev_branch(self):
        if not self.branches:
            return
        if self.selected_branch is None:
            self.selected_branch = self.branches[-1].name
        else:
            for i, b in enumerate(self.branches):
                if b.name == self.selected_branch and i > 0:
                    self.selected_branch = self.branches[i - 1].name
                    break

    def select_left_branch(self):
        if self.selected_index < len(self.commits):
            commit = self.commits[self.selected_index]
            branches_at_commit = [b for b in self.branches if b.commit_hash == commit.short_hash]
            if not branches_at_commit:
                return

            if self.selected_branch is None:
                self.selected_branch = branches_at_commit[0].name
            else:
                for i, b in enumerate(branches_at_commit):
                    if b.name == self.selected_branch and i > 0:
                        self.selected_branch = branches_at_commit[i - 1].name
                        break

    def select_right_branch(self):
        if self.selected_index < len(self.commits):
            commit = self.commits[self.selected_index]
            branches_at_commit = [b for b in self.branches if b.commit_hash == commit.short_hash]
            if not branches_at_commit:
                return

            if self.selected_branch is None:
                self.selected_branch = branches_at_commit[0].name
            else:
                for i, b in enumerate(branches_at_commit):
                    if b.name == self.selected_branch and i < len(branches_at_commit) - 1:
                        self.selected_branch = branches_at_commit[i + 1].name
                        break

    def jump_to_head(self):
        for i, commit in enumerate(self.commits):
            if commit.is_head:
                self.selected_index = i
                break

    def toggle_help(self):
        self.help_open = not self.help_open

    def checkout_selected(self):
        if self.selected_index < len(self.commits):
            commit = self.commits[self.selected_index]
            self.repo.checkout(commit.hash)
            self.refresh_data()

    def fetch_from_origin(self):
        self.repo.fetch()
        self.refresh_data()

    def get_selected_commit(self) -> Optional[CommitInfo]:
        if self.selected_index < len(self.commits):
            return self.commits[self.selected_index]
        return None

    def draw(self):
        try:
            self.stdscr.clear()
            height, width = self.stdscr.getmaxyx()

            if self.help_open:
                self.draw_help(height, width)
            else:
                self.draw_main(height, width)

            self.stdscr.refresh()
        except curses.error:
            pass

    def draw_main(self, height, width):
        # Split layout
        commit_height = int(height * 0.7)
        detail_height = height - commit_height - 1

        # Draw commits area
        self.draw_commits(0, 0, height - 1, width, commit_height)

        # Draw details
        detail_width = width // 2
        self.draw_commit_detail(commit_height, 0, detail_height, detail_width)
        self.draw_changed_files(commit_height, detail_width, detail_height, width - detail_width)

        # Draw footer
        self.draw_footer(height - 1, 0, width)

    def draw_commits(self, y, x, max_y, width, height):
        # Header
        try:
            self.stdscr.attron(curses.color_pair(0))
            header = "┌ Commits " + "─" * max(1, width - 12) + "┐"
            self.stdscr.addstr(y, x, header[:width])
        except curses.error:
            pass

        # Compute visible range
        visible_height = height - 2
        if visible_height < 1:
            return

        start = max(0, self.selected_index - visible_height // 2)
        end = min(len(self.commits), start + visible_height)
        start = min(start, max(0, len(self.commits) - visible_height))

        # Draw commits
        for i, commit in enumerate(self.commits[start:end]):
            if i >= visible_height:
                break

            row = i + y + 1
            if row >= max_y:
                break

            is_selected = (start + i) == self.selected_index

            # Get branches at this commit
            branch_str = ""
            branches_here = [b for b in self.branches if b.commit_hash == commit.short_hash]
            if branches_here:
                branch_names = [f"[{b.name}]" for b in branches_here]
                branch_str = " ".join(branch_names)

            graph_char = "◉" if commit.is_head else "●"

            if branch_str:
                msg_display = branch_str[:40]
            else:
                msg_display = commit.message[:40]

            line = f" {graph_char}    {msg_display:<40} {commit.date} {commit.author:<10} {commit.short_hash}"
            line = line[:width]

            try:
                if is_selected:
                    self.stdscr.attron(curses.color_pair(1) | curses.A_BOLD)
                else:
                    self.stdscr.attron(curses.color_pair(0))

                self.stdscr.addstr(row, x, line)
                self.stdscr.attroff(curses.color_pair(1) | curses.A_BOLD)
            except curses.error:
                pass

        # Border bottom
        try:
            bottom = "└" + "─" * max(1, width - 2) + "┘"
            self.stdscr.addstr(y + height - 1, x, bottom[:width])
        except curses.error:
            pass

    def draw_commit_detail(self, y, x, height, width):
        try:
            self.stdscr.attron(curses.color_pair(0))
            header = "┌ Commit Detail " + "─" * max(1, width - 18) + "┐"
            self.stdscr.addstr(y, x, header[:width])
        except curses.error:
            pass

        commit = self.get_selected_commit()
        if commit:
            try:
                row = y + 1
                if row < y + height - 1:
                    line = f"Commit: {commit.hash[:7]}"[:width-2]
                    self.stdscr.addstr(row, x + 1, line)
                row += 1
                if row < y + height - 1:
                    line = f"Author: {commit.author}"[:width-2]
                    self.stdscr.addstr(row, x + 1, line)
                row += 1
                if row < y + height - 1:
                    line = f"Date:   {commit.date}"[:width-2]
                    self.stdscr.addstr(row, x + 1, line)
                row += 1
                if commit.parent_hashes and row < y + height - 1:
                    line = f"Parent: {', '.join(commit.parent_hashes)}"[:width-2]
                    self.stdscr.addstr(row, x + 1, line)
                row += 1
                if row < y + height - 1:
                    self.stdscr.addstr(row, x + 1, "")
                row += 1
                if row < y + height - 1:
                    msg = commit.message[:width-2]
                    self.stdscr.addstr(row, x + 1, msg)
            except curses.error:
                pass

        try:
            bottom = "└" + "─" * max(1, width - 2) + "┘"
            self.stdscr.addstr(y + height - 1, x, bottom[:width])
        except curses.error:
            pass

    def draw_changed_files(self, y, x, height, width):
        try:
            self.stdscr.attron(curses.color_pair(0))
            header = "┌ Changed Files " + "─" * max(1, width - 18) + "┐"
            self.stdscr.addstr(y, x, header[:width])
        except curses.error:
            pass

        commit = self.get_selected_commit()
        if commit:
            try:
                additions, deletions, files = self.repo.get_commit_diff(commit.hash)

                row = y + 1
                if row < y + height - 1:
                    stat_line = f"{len(files)} files changed  +{additions} -{deletions}"[:width-2]
                    self.stdscr.addstr(row, x + 1, stat_line)

                row += 2
                for f in files[:10]:
                    if row < y + height - 1:
                        file_line = f" {f} +1 -0"[:width-2]
                        self.stdscr.addstr(row, x + 1, file_line)
                        row += 1
            except Exception:
                pass

        try:
            bottom = "└" + "─" * max(1, width - 2) + "┘"
            self.stdscr.addstr(y + height - 1, x, bottom[:width])
        except curses.error:
            pass

    def draw_footer(self, y, x, width):
        try:
            repo_name = os.path.basename(os.getcwd())
            branch = self.selected_branch or "detached"

            footer = f" {repo_name}   {branch}   j/k move  Enter checkout  b branch  f fetch  ? help  q quit"
            footer = footer[:width]
            footer += " " * (width - len(footer))

            self.stdscr.attron(curses.color_pair(0))
            self.stdscr.addstr(y, x, footer)
        except curses.error:
            pass

    def draw_help(self, height, width):
        try:
            # Center dialog
            dialog_width = 60
            dialog_height = 25
            start_x = max(0, (width - dialog_width) // 2)
            start_y = max(0, (height - dialog_height) // 2)

            # Draw box
            self.stdscr.attron(curses.color_pair(0))
            header = "┌ Help " + "─" * max(1, dialog_width - 8) + "┐"
            self.stdscr.addstr(start_y, start_x, header[:dialog_width])

            help_lines = [
                "",
                "Navigation",
                "  j / ↓      Move down",
                "  k / ↑      Move up",
                "  ] / Tab    Select next branch",
                "  [ / S-Tab  Select previous branch",
                "  h / ←      Select left branch (same commit)",
                "  l / →      Select right branch (same commit)",
                "  Ctrl+d     Page down",
                "  Ctrl+u     Page up",
                "  g / Home   Go to top",
                "  G / End    Go to bottom",
                "  @          Jump to HEAD (current branch)",
                "",
                "Git Operations",
                "  Enter      Checkout selected branch/commit",
                "  b          Create new branch",
                "  d          Delete branch",
                "  f          Fetch from origin",
            ]

            for i, line in enumerate(help_lines):
                if i < dialog_height - 2:
                    row = start_y + 1 + i
                    display_line = line[:dialog_width-2]
                    self.stdscr.addstr(row, start_x + 1, display_line)

            bottom = "└" + "─" * max(1, dialog_width - 2) + "┘"
            self.stdscr.addstr(start_y + dialog_height - 1, start_x, bottom[:dialog_width])
        except curses.error:
            pass

    def run(self):
        # Setup colors
        try:
            curses.curs_set(0)  # Hide cursor
        except:
            pass

        if curses.has_colors():
            try:
                curses.init_pair(1, curses.COLOR_WHITE, curses.COLOR_BLACK)
            except:
                pass

        self.stdscr.nodelay(1)  # Non-blocking input
        self.stdscr.timeout(250)  # Timeout for getch

        while self.running:
            self.draw()

            try:
                ch = self.stdscr.getch()

                if ch == ord('q') or ch == 27:  # ESC
                    self.running = False
                elif ch == ord('j') or ch == curses.KEY_DOWN:
                    self.move_down()
                elif ch == ord('k') or ch == curses.KEY_UP:
                    self.move_up()
                elif ch == ord('g') or ch == curses.KEY_HOME:
                    self.go_to_top()
                elif ch == ord('G') or ch == curses.KEY_END:
                    self.go_to_bottom()
                elif ch == ord('l') or ch == curses.KEY_RIGHT:
                    self.select_right_branch()
                elif ch == ord('h') or ch == curses.KEY_LEFT:
                    self.select_left_branch()
                elif ch == 9:  # Tab
                    self.select_next_branch()
                elif ch == ord('['):
                    self.select_prev_branch()
                elif ch == ord(']'):
                    self.select_next_branch()
                elif ch == ord('?'):
                    self.toggle_help()
                elif ch == ord('@'):
                    self.jump_to_head()
                elif ch == 10 or ch == 13:  # Enter
                    if self.help_open:
                        self.toggle_help()
                    else:
                        self.checkout_selected()
                elif ch == ord('b'):
                    pass  # Branch creation (TODO)
                elif ch == ord('d'):
                    pass  # Branch deletion (TODO)
                elif ch == ord('f'):
                    self.fetch_from_origin()
                elif ch == ord('R') or ch == ord('r'):
                    self.refresh_data()
                elif ch == -1:  # timeout
                    pass

                # Auto-refresh
                current_time = time.time()
                if (self.config.refresh.auto_refresh and 
                    current_time - self.last_refresh >= self.config.refresh.refresh_interval):
                    self.refresh_data()

                if (self.config.refresh.auto_fetch and 
                    current_time - self.last_fetch >= self.config.refresh.fetch_interval):
                    self.fetch_from_origin()

            except curses.error:
                pass
            except KeyboardInterrupt:
                self.running = False
            except Exception:
                pass

def main():
    if len(sys.argv) > 1:
        if sys.argv[1] in ['--help', '-h']:
            print("A TUI tool to visualize Git commit graphs with branch genealogy\n")
            print("Usage: executable\n")
            print("Options:")
            print("  -h, --help     Print help")
            print("  -V, --version  Print version")
            sys.exit(0)
        elif sys.argv[1] in ['--version', '-V']:
            print("keifu 0.2.3")
            sys.exit(0)
        else:
            print(f"Unknown option: {sys.argv[1]}")
            sys.exit(1)

    try:
        # Check if we're in a git repo before initializing curses
        repo = GitRepository('.')
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

    try:
        curses.wrapper(lambda stdscr: App(stdscr).run())
    except KeyboardInterrupt:
        pass
    except Exception as e:
        print(f"Error: {e}")
        import traceback
        traceback.print_exc()
        sys.exit(1)

if __name__ == '__main__':
    main()
